llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C20"],
      "claim": "Codeine, a close morphinan analogue sharing the methoxyaryl, allylic alcohol, ether bridge, and N-methylamine features with the query, has absolute oral bioavailability of 42–71% in healthy volunteers, directly supporting F ≥ 20% for the query scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C19"],
      "claim": "Codeine sulfate reached 80.5% oral bioavailability in healthy subjects, demonstrating that this alkaloid scaffold can be highly orally available.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "Ethylmorphine, the 3-O-ethyl analogue of codeine, had median oral systemic availability of 74% (range 54–92%) in healthy subjects, supporting high oral bioavailability for close analogues.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Noscapine, a related rigid polycyclic ether-amine opium alkaloid, has absolute oral bioavailability of 30%, above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "Morphine, a close congener, has systemic availability of 38% in cancer patients, supporting F ≥ 20% for the structural family.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is galanthamine, a rigid alkaloid closely related to codeine and ethylmorphine; multiple direct analogues show oral bioavailability well above 20%, and the physicochemical prior is favorable, so F ≥ 20% is predicted.",
  "evidence_gaps": [
    "No direct galanthamine-specific bioavailability record is present in the evidence set.",
    "Morphine records vary around 20–45%, with a few estimates slightly below 20%, introducing some uncertainty in extrapolation.",
    "Low-bioavailability records (tetrabenazine, terameprocol, ThH) are from structurally distinct scaffolds and were not used as primary evidence."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

